type Handler<K extends keyof Events> = (payload: Events[K]) => void

on<K extends keyof Events>(name: K, handler: Handler<K>): void {
  const list = this.handlers[name] ?? []
  list.push(handler as Handler<keyof Events>)
  this.handlers[name] = list
}

emit<K extends keyof Events, P extends Events[K]>(name: K, payload: P): void {
  for (const handler of this.handlers[name] ?? []) handler(payload)
}

emit<K extends keyof Events>(name: K, payload: Events[K]): void {
  for (const handler of this.handlers[name] ?? []) handler(payload)
}

export type Listeners = {
  [K in keyof Events as `on${Capitalize<string & K>}`]: (payload: Events[K]) => unknown
}
